/**
 * Mind mapping plugin for TinyMCE
 *
 * Released under the MIT license.
 * Author: Ignacio Gros (http://gros.es/) for http://exelearning.net/ 
 *
 * The editor (editor/) is built with Mind Elixir (https://github.com/SSShooter/mind-elixir-core)
 * and @erseco/mind-elixir-export-svg, both under the MIT license. Each map is stored as an
 * SVG image plus the map's JSON to edit it again.
 * Maps made with the previous editor, mindmaps (https://github.com/drichard/mindmaps), by
 * David Richard, are converted when they are opened (editor/src/storedMindmap.ts).
 *
 * Plugin icons by Google (https://material.io/tools/icons/), available under the Apache license version 2.0. (http://www.apache.org/licenses/LICENSE-2.0)
 */
tinymce.PluginManager.add('exemindmap', function (editor, url) {

    let $ = tinymce.dom.DomQuery;

    /**
     * The editor page. In server mode it goes through composeUrl() so that BASE_PATH is
     * prepended: a bare "/api/..." URL 404s behind a reverse proxy that only mounts the
     * BASE_PATH namespace (issue #1802). Static mode, offline installations and Electron use
     * the file next to the app with a relative path, which works at any subdirectory depth
     * (at /dist/static/index.html, ./libs/... resolves to /dist/static/libs/...).
     */
    function getEditorUrl() {
        var editorUrl = (window.eXeLearning && window.eXeLearning.app && typeof window.eXeLearning.app.composeUrl === 'function')
            ? window.eXeLearning.app.composeUrl('/api/exemindmap-editor/index.html')
            : '/api/exemindmap-editor/index.html';
        var config = window.eXeLearning?.config;
        if (typeof config === 'string') {
            try { config = JSON.parse(config); } catch(e) { config = null; }
        }
        if (config?.isStaticMode || config?.isOfflineInstallation || window.__EXE_STATIC_MODE__ || window.electronAPI) {
            editorUrl = "./libs/tinymce_5/js/tinymce/plugins/exemindmap/editor/index.html";
        }
        return editorUrl;
    }

    /** The map that contains the selection (any element inside it), as the editor opens it. */
    function getSelectedMap() {
        var elm = editor.selection.getNode();
        elm = elm && elm.closest ? elm.closest(".exe-mind-map") : null;
        var code = elm ? elm.querySelector(".exe-mindmap-code") : null;
        if (!code) return null;
        var title = elm.querySelector(".title");
        var img = elm.querySelector("img");
        return {
            element: elm,
            code: code.innerHTML,
            title: title ? title.textContent : (img && img.getAttribute("alt")) || "",
            caption: !!title
        };
    }

    // One per editor: an iDevice can have several TinyMCE instances (a Text iDevice has two)
    const eXeMediaPluginDialog = {

        /**
         * Opens the editor in one TinyMCE URL dialog. The editor iframe and this plugin talk with
         * TinyMCE's dialog messages, which TinyMCE only accepts from the editor's origin:
         * exeMindmapReady (editor) → exeMindmapLoad (plugin: the map, its title and caption);
         * Save → exeMindmapSave (plugin) → exeMindmapSaved (editor: JSON, SVG, title, caption) or
         * exeMindmapFailed (the editor shows why). Cancel and the close button change nothing.
         */
        openDialog: function () {
            // The map being edited, or null for a new one. It is kept here, not looked up again
            // on save, so the map that was opened is the one replaced.
            var target = getSelectedMap();
            var ready = false;
            var saving = false;

            editor.windowManager.openUrl({
                title: _('Mind map'),
                url: getEditorUrl(),
                buttons: [
                    {
                        type: 'cancel',
                        name: 'cancel',
                        text: _('Cancel')
                    },
                    {
                        type: 'custom',
                        name: 'save',
                        text: _('Save'),
                        primary: true
                    }
                ],
                onAction: function (api, details) {
                    if (details.name !== 'save' || !ready || saving) return;
                    saving = true;
                    // Covers the dialog, its buttons included, until the editor answers
                    api.block(_('Saving...'));
                    api.sendMessage({ mceAction: 'exeMindmapSave' });
                },
                onMessage: function (api, message) {
                    if (message.mceAction === 'exeMindmapReady') {
                        ready = true;
                        api.sendMessage({
                            mceAction: 'exeMindmapLoad',
                            code: target ? target.code : '',
                            title: target ? target.title : '',
                            caption: target ? target.caption : true
                        });
                    } else if (message.mceAction === 'exeMindmapSaved' && saving) {
                        var error = eXeMediaPluginDialog.insertMap(target ? target.element : null, message);
                        if (!error) {
                            api.close();
                            return;
                        }
                        saving = false;
                        api.unblock();
                        api.sendMessage({ mceAction: 'exeMindmapError', message: error });
                    } else if (message.mceAction === 'exeMindmapFailed') {
                        saving = false;
                        api.unblock();
                    }
                }
            });
        },

        /**
         * Inserts the saved map, or replaces `target` with it, as one undo step.
         * Returns an error message, and changes nothing, when the editor's data is not usable.
         */
        insertMap: function (target, data) {
            var code = typeof data.code === 'string' ? data.code : '';
            var img = typeof data.svg === 'string' ? data.svg : '';
            var title = eXeMediaPluginDialog.stripHtml(String(data.title || '')).trim();
            // The editor escapes the JSON, so it starts with "{" and holds no markup
            if (code.indexOf('{') != 0 || /[<>]/.test(code) || img.indexOf('data:image/svg+xml;base64,') != 0) {
                return _('Please create a mind map.');
            }
            if (title == "") return _('Please provide a title.');

            // The image's alt names it; the caption is optional, as in legacy maps
            var escapedTitle = eXeMediaPluginDialog.escapeHtml(title);
            var w = Math.round(data.width) || 600;
            var h = Math.round(data.height) || 400;
            var figcaption = data.caption
                ? '<figcaption class="figcaption"><span class="title"><em>' + escapedTitle + '</em></span></figcaption>'
                : '';

            var content = `
                    <div class="exe-mind-map">
                        <figure class="exe-figure exe-image position-center" style="width: ${w}px;">
                            <img src="${eXeMediaPluginDialog.escapeHtml(img)}" width="${w}" height="${h}" alt="${escapedTitle}">
                            ${figcaption}
                        </figure>
                        <p class="exe-mindmap-code">${code}</p>
                    </div>
                    `;

            try {
                editor.undoManager.transact(function () {
                    if (target && editor.getBody().contains(target)) {
                        // Replace the whole map where it is
                        editor.selection.select(target);
                        editor.selection.setContent(content);
                    } else {
                        content += "..."; // Add a P after the map
                        editor.insertContent(content);
                    }
                });
            } catch (e) {
                return String(e && e.message || e);
            }

            eXeMediaPluginDialog.showMindMapsTitles(editor);
            return '';
        },

        showMindMapsTitles: function (editor) {
            var d = editor.getDoc();
            jQuery("HEAD #eXeMediaPluginDialogCSS", d).remove();
            var s = '<style type="text/css" id="eXeMediaPluginDialogCSS">';
            jQuery(".exe-mind-map", d).each(function (i) {
                var title = $(".title", this);
                title = title.length == 1 ? title.text() : $("img", this).attr("alt");
                // A CSS string that cannot close the rule or the style element
                if (title) s += '.exe-mind-map:nth-of-type(' + (i + 1) + '):before{content:' + JSON.stringify(title).replace(/</g, '\\3c ') + '}';
            });
            s += '</style>';
            jQuery("HEAD", d).append(s);
        },

        activateButton: function (node) {
            var e = jQuery(node);
            if (e.attr("class") == 'exe-mind-map') return true;
            if (e.parents(".exe-mind-map").length > 0) return true;
            return false;
        },

        escapeHtml: function (text) {
            return text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
        },

        stripHtml: function (html) {
            var tmp = document.createElement("DIV");
            tmp.innerHTML = html;
            return tmp.textContent || tmp.innerText || "";
        }

    }; // Dialog

    // Plugin button
    editor.ui.registry.addIcon('exemindmap', '<svg xmlns="http://www.w3.org/2000/svg" height="24" viewBox="0 0 24 24" width="24"><path d="M0 0h24v24H0z" fill="none"/><path d="M22 11V3h-7v3H9V3H2v8h7V8h2v10h4v3h7v-8h-7v3h-2V8h2v3z"/></svg>');
    editor.ui.registry.addToggleButton('exemindmap', {
        icon: 'exemindmap',
        tooltip: _('Mind map'),
        onAction: eXeMediaPluginDialog.openDialog,
        onSetup: function (buttonApi) {
            var editorEventCallback = function (eventApi) {
                buttonApi.setActive(eXeMediaPluginDialog.activateButton(eventApi.element));
            };
            editor.on('NodeChange', editorEventCallback);
            return function (buttonApi) {
                editor.off('NodeChange', editorEventCallback);
            }
        }
    });

    editor.on('init', function (e) {
        editor.dom.loadCSS(url + "/css/content.css");
        eXeMediaPluginDialog.showMindMapsTitles(editor);
    });

});